import { Avatar, AvatarGroup } from "@databricks/design-system"

{/* size: 'xxs'|'xs'|'sm'|'md'|'lg'|'xl', background: 'indigo'|'teal'|'pink'|'purple'|'brown' */}
<Avatar type="user" size="md" background="indigo" />

import { Button } from "@databricks/design-system"

{/* Default (secondary) — no type prop */}
<Button>Label</Button>

import { Pagination } from "@databricks/design-system"

{/* Wraps AntD Pagination */}
<Pagination currentPageIndex={0} numPages={10} onChange={fn} />

import { Spinner } from "@databricks/design-system"

{/* size: 'small' | 'default' | 'large' */}
<Spinner size="default" label="Loading..." />

import { SplitButton } from "@databricks/design-system"

{/* Default type — no type prop */}
<SplitButton size="middle">Label</SplitButton>

import { ResourceStatusIndicator } from "@databricks/design-system"

{/* DuBois only supports 3 statuses: online, disconnected, offline */}
<ResourceStatusIndicator status="online" />
